// (v0.1.4 버그 수정) AnimatePresence의 popLayout 모드는 퇴장 애니메이션 동안 레이아웃을 측정하려고
// 직계 자식에 ref를 직접 꽂는다 — FadeIn이 일반 함수 컴포넌트라 그 ref를 못 받아 React가 경고를
// 냈다(분석 탭 수 블록 목록에서 발견). forwardRef로 감싸 motion.div에 그대로 전달한다.
const FadeIn = React.forwardRef(function FadeIn({ children, index = 0, y = 12, layout = true, className, style }, ref) {
  return (
    <motion.div ref={ref} layout={layout} initial={{ opacity: 0, y }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -8, scale: 0.97 }}
      transition={{ duration: 0.32, delay: Math.min(index, 12) * 0.035, ease: MOTION_EASE }} className={className} style={style}>
      {children}
    </motion.div>
  );
});
// (17차) 배경 장식의 기하학적 밀도 강화 — 저폴리곤 기물 아이콘과 어울리도록 와이어프레임 큐브·정팔면체·
// 육각형 등을 페이지 전반(상단뿐 아니라 하단까지)에 흩뿌려 첨부 레퍼런스 이미지의 "떠있는 도형들" 느낌을 낸다.
// (v0.0.5 성능) props 없는 순수 장식 SVG인데도 memo가 없으면 App이 리렌더될 때마다(3~30초 폴링 등)
// 매번 다시 그려졌다 — React.memo로 최초 한 번만 계산하도록 고정.
const GeoBackdrop = React.memo(function GeoBackdrop() {
  const g = "#C49A50";
  const dia = (x, y, sz, o) => <rect x={x} y={y} width={sz} height={sz} transform={"rotate(45 " + (x + sz / 2) + " " + (y + sz / 2) + ")"} fill="none" stroke={g} strokeWidth="1.2" opacity={o} />;
  const tri = (x, y, sz, o, filled) => <path d={"M" + x + " " + (y - sz) + " L" + (x + sz * 0.87) + " " + (y + sz * 0.5) + " L" + (x - sz * 0.87) + " " + (y + sz * 0.5) + " Z"} fill={filled ? g : "none"} stroke={g} strokeWidth="1" opacity={o} />;
  // 와이어프레임 큐브(등각투상 육각형 실루엣 + 내부 3면 경계선)
  const cube = (x, y, sz, o) => (
    <g opacity={o} fill="none" stroke={g} strokeWidth="1">
      <path d={"M" + x + "," + (y - sz * 0.5) + " L" + (x + sz * 0.87) + "," + (y - sz) + " L" + (x + sz * 1.74) + "," + (y - sz * 0.5) + " L" + (x + sz * 1.74) + "," + (y + sz * 0.5) + " L" + (x + sz * 0.87) + "," + (y + sz) + " L" + x + "," + (y + sz * 0.5) + " Z"} />
      <path d={"M" + x + "," + (y - sz * 0.5) + " L" + (x + sz * 0.87) + "," + y + " L" + (x + sz * 1.74) + "," + (y - sz * 0.5)} />
      <line x1={x + sz * 0.87} y1={y} x2={x + sz * 0.87} y2={y + sz} />
    </g>
  );
  // 정팔면체(가로선으로 나뉜 마름모) 실루엣
  const octa = (x, y, w, h, o) => (
    <g opacity={o} fill="none" stroke={g} strokeWidth="1">
      <path d={"M" + x + "," + (y - h) + " L" + (x + w) + "," + y + " L" + x + "," + (y + h) + " L" + (x - w) + "," + y + " Z"} />
      <line x1={x - w} y1={y} x2={x + w} y2={y} />
    </g>
  );
  const hexOutline = (x, y, sz, o) => { const pts = Array.from({ length: 6 }, (_, i) => { const a = Math.PI / 3 * i - Math.PI / 6; return (x + sz * Math.cos(a)) + "," + (y + sz * Math.sin(a)); }).join(" "); return <polygon points={pts} fill="none" stroke={g} strokeWidth="1" opacity={o} />; };
  return (
    <svg aria-hidden="true" width="100%" height="100%" viewBox="0 0 1200 1600" preserveAspectRatio="xMidYMin slice" style={{ position: "fixed", inset: 0, zIndex: -1, pointerEvents: "none" }}>
      <g fill="none" stroke={g}>
        <circle cx="600" cy="230" r="360" strokeWidth="1.2" opacity="0.10" />
        <circle cx="600" cy="230" r="250" strokeWidth="1" opacity="0.07" strokeDasharray="2 9" />
        <circle cx="120" cy="980" r="220" strokeWidth="1" opacity="0.06" strokeDasharray="2 9" />
        <circle cx="1100" cy="1300" r="300" strokeWidth="1.1" opacity="0.07" />
        <line x1="0" y1="230" x2="1200" y2="230" strokeWidth="1" opacity="0.05" />
        <line x1="600" y1="-120" x2="600" y2="600" strokeWidth="1" opacity="0.05" />
        <line x1="110" y1="-60" x2="540" y2="370" strokeWidth="1" opacity="0.06" />
        <line x1="1090" y1="-60" x2="660" y2="370" strokeWidth="1" opacity="0.06" />
        <line x1="80" y1="1480" x2="420" y2="1120" strokeWidth="1" opacity="0.05" />
        <line x1="1150" y1="1500" x2="820" y2="1080" strokeWidth="1" opacity="0.05" />
      </g>
      {dia(150, 350, 28, 0.12)}{dia(1006, 286, 32, 0.12)}{dia(978, 520, 16, 0.09)}{dia(214, 560, 16, 0.08)}
      {dia(90, 1180, 20, 0.09)}{dia(1120, 940, 24, 0.1)}{dia(760, 1460, 18, 0.08)}
      <path d="M120 940 L140 902 L160 940 Z" fill={g} opacity="0.08" />
      <path d="M1058 1010 L1078 972 L1098 1010 Z" fill={g} opacity="0.08" />
      {tri(340, 1240, 16, 0.1, true)}{tri(980, 1180, 12, 0.08, false)}{tri(1140, 640, 14, 0.09, false)}
      {cube(60, 500, 26, 0.09)}{cube(1000, 760, 22, 0.08)}{cube(300, 1360, 20, 0.07)}{cube(880, 1440, 24, 0.08)}
      {octa(1080, 200, 22, 30, 0.09)}{octa(180, 800, 18, 26, 0.08)}{octa(620, 1000, 16, 22, 0.07)}{octa(1000, 1240, 20, 28, 0.08)}
      {hexOutline(500, 880, 34, 0.06)}{hexOutline(1140, 480, 26, 0.07)}{hexOutline(220, 1480, 30, 0.06)}
      {/* (17차) 버튼/카드 개별 장식(geo-cut, geo-card)을 제거하는 대신, 배경(갈색 여백)의 기하학 밀도를
          더 높여 첨부 레퍼런스의 "떠있는 도형들" 느낌을 UI 블록이 아닌 배경 쪽에서만 낸다. */}
      {dia(430, 140, 14, 0.08)}{dia(690, 660, 18, 0.07)}{dia(60, 760, 12, 0.08)}{dia(1150, 1120, 16, 0.07)}
      {dia(360, 1560, 20, 0.07)}{dia(940, 60, 14, 0.08)}
      <path d="M540 480 L556 448 L572 480 Z" fill={g} opacity="0.07" />
      <path d="M800 1300 L818 1266 L836 1300 Z" fill={g} opacity="0.07" />
      {tri(60, 1040, 12, 0.08, false)}{tri(1180, 320, 10, 0.09, true)}{tri(460, 1500, 14, 0.07, false)}
      {cube(500, 60, 16, 0.07)}{cube(1150, 560, 18, 0.07)}{cube(40, 1440, 20, 0.07)}
      {octa(360, 240, 14, 20, 0.07)}{octa(860, 900, 18, 24, 0.06)}
      {hexOutline(60, 260, 20, 0.06)}{hexOutline(700, 1560, 24, 0.06)}{hexOutline(1180, 900, 18, 0.06)}
      <circle cx="500" cy="1140" r="3" fill={g} opacity="0.15" />
      <circle cx="1080" cy="700" r="2.4" fill={g} opacity="0.14" />
      <circle cx="240" cy="440" r="2.6" fill={g} opacity="0.13" />
      <circle cx="900" cy="1440" r="3" fill={g} opacity="0.14" />
    </svg>
  );
});

const ENGINE_BASE = (typeof import.meta !== "undefined" && import.meta.env && import.meta.env.BASE_URL) ? import.meta.env.BASE_URL : "/";
/* (v0.2.4 개편 → v0.3.5 통합 → 8z5dbt 세션 기능 추가) 엔진 선택 — 예전엔 "분석"(학습/퍼즐 탭 및
   사이트 전반)과 "게임 리뷰"가 서로 다른 엔진을 썼다("full", Stockfish 16을 게임 리뷰 전용 고정
   엔진으로 사람 최상급 수준까지 세기를 제한해 썼다). 사용자 요청으로 이제 게임 리뷰도 설정 탭에서
   고른 분석 엔진을 그대로 쓰도록 통합하고, Stockfish 16("full" 프로필)은 완전히 폐기했다
   (engine/stockfish-nnue-16* 파일·npm 별칭도 함께 제거 — scripts/copy-engine.mjs, package.json
   참고). "lite"(Stockfish 18 Lite, 기기 종류와 무관하게 기본값), "full17"(Stockfish 17.1, 정식
   대형 신경망 — 약 80MB, 여러 조각으로 나눠 받는다), "full18"(Stockfish 18 정식 대형 신경망, 셋 중
   가장 강력함 — 약 108MB, 마찬가지로 조각으로 나눠 받는다) 중에서 설정 탭에서 고를 수 있고, 이후에는
   그 선택을 기억한다. */
const ENGINE_PROFILES = {
  lite: {
    id: "lite", label: "Stockfish 18 Lite",
    urls: [ENGINE_BASE + "engine/lite/stockfish-18-lite-single.js", "https://cdn.jsdelivr.net/npm/stockfish@18.0.8/bin/stockfish-18-lite-single.js"],
    mtUrl: ENGINE_BASE + "engine/lite/stockfish-18-lite.js",
  },
  // (v0.2.0 기능) 분석 엔진 중 최고 성능 — Stockfish 17.1의 정식(비-Lite) 대형 신경망 빌드. 신경망
  // 파일이 npm 배포 용량 제한 때문에 여러 조각으로 쪼개져 있어(scripts/copy-engine.mjs 참고),
  // 조각을 이어 붙이는 부트스트랩 스크립트(boot-single.js/boot-mt.js)를 거쳐 불러온다 — 용량이 큰
  // 만큼 같은 출처(public/engine) 파일만 쓰고 CDN 폴백은 두지 않는다(실패하면 다른 프로필처럼
  // 엔진이 "연결 실패" 상태가 될 뿐, 앱 자체는 계속 정상 동작한다).
  // (버그 수정) 로더 스크립트는 조각 파일 이름(base-part-N.wasm)을 "자기 자신을 실행 중인 워커의
  // location"에서 유추하는데, importScripts로 불러와도 워커의 location은 그 워커를 처음 만들 때
  // 준 URL(boot-single.js) 그대로다 — 그래서 "boot-single-part-0.wasm"(존재하지 않음)을 찾다가
  // 실패했다. 그 스크립트는 self.location.hash가 있으면 그 값을 실제 신경망 파일명으로 우선
  // 사용하므로, URL 뒤에 "#진짜파일명.wasm"을 붙여 워커를 만들면(importScripts 이후에도 hash는
  // 그대로 유지된다) 같은 폴더의 조각 파일을 정확히 찾아낸다.
  full17: {
    id: "full17", label: "Stockfish 17.1",
    urls: [ENGINE_BASE + "engine/17/boot-single.js#stockfish-17.1-single-a496a04.wasm"],
    mtUrl: ENGINE_BASE + "engine/17/boot-mt.js#stockfish-17.1-8e4d048.wasm",
    parts: 6,   // 부팅 타임아웃을 넉넉히 주기 위한 표시(engineBootList 참고) — 실제 조각 이어붙이기는 boot-*.js 안에서 처리된다.
  },
  // (8z5dbt 세션 기능) 셋 중 가장 강력한 엔진 — Stockfish 18의 정식(비-Lite) 대형 신경망 빌드. npm
  // 패키지가 이 빌드는 조각내지 않고 wasm 파일 하나(~108MB)로만 배포해서, Vercel의 배포 파일당
  // 100MB 제한을 넘는다.
  // (v0.4.9, 폐기됨) 빌드 시점마다 100MB 미만 조각으로 직접 쪼개 public/engine/18에 뒀었는데(단일+
  // 멀티스레드 두 빌드 합쳐 약 216MB라 매 배포마다 다시 패키징돼 Vercel Deployment Storage 10GB
  // 무료 한도 초과의 주범이 됨), 그래서 Vercel Blob 업로드로 옮겼다.
  // (v0.5.1, 폐기됨) Vercel Blob → GitHub Release로 외부 저장소를 두 번 옮겨 봤지만 둘 다 실패했다 —
  // Blob은 원인 불명의 다운로드 실패(재업로드해도 URL 동일, 194MB 전송까지 Network 탭으로 확인됐는데도
  // 몇 분이 지나도 끝나지 않음), GitHub Release는 애초에 브라우저 fetch용 CORS 헤더 자체를 보내지
  // 않아(release-assets.githubusercontent.com 응답에 Access-Control-Allow-Origin이 없음 — curl로
  // 직접 확인) 모든 시도가 브라우저에서 조용히 막혔다. 외부 저장소가 계속 새로운 종류의 문제를 만들어,
  // 사용자 요청으로 원래 방식(같은 출처에서 직접 서빙)으로 되돌렸다 — 같은 출처면 CORS 문제 자체가
  // 없다. v0.4.9 때와 다른 점은 이제 멀티스레드(mtUrl) 빌드를 포기해서(이전 세션에서 이미 결정 —
  // 신뢰성이 스레드 성능 이득보다 중요하다고 판단) 배포 용량 증가분이 절반(~108MB)뿐이라는 것 — 이미
  // 같은 방식으로 서빙 중인 17.1(~80MB)과 비슷한 수준이라, 그 프로필이 이미 감수하고 있는 위험과
  // 다르지 않다. 조각 나누기·재조립은 scripts/copy-engine.mjs가 빌드마다 다시 만든다(자세한 내용은
  // 그 스크립트의 주석 참고) — 17.1과 달리 stockfish18 npm 로더는 조각 재조립 기능을 자체 지원하지
  // 않아 self.fetch를 가로채는 방식을 쓴다.
  full18: {
    id: "full18", label: "Stockfish 18",
    urls: [ENGINE_BASE + "engine/18/boot-single.js"],
    // 신경망이 108MB라 느린 회선에서는 받는 데 시간이 걸릴 수 있어 넉넉히 둔다(v0.5.1).
    bootTimeoutMs: 240000,
    // analyzePoolSize/getAnalysisPool이 이 프로필을 "무거운 프로필"로 식별해 게임 리뷰용 풀 부팅
    // 경합을 줄이도록(HEAVY_ENGINE_POOL_SIZE·HEAVY_ENGINE_BOOT_BATCH) parts를 그대로 쓴다(17.1과
    // 같은 처리 — 실제 조각 수는 scripts/copy-engine.mjs가 계산하지만, 여기서는 "무겁다"는 표시로만
    // 쓰이므로 정확한 개수가 아니어도 무방하다).
    parts: 2,
  },
};
// (v0.2.4) 설정 탭에서 고를 수 있는 분석 엔진 — v0.3.5부터 게임 리뷰도 이 중에서 고른 엔진을 그대로 쓴다.
// (v0.3.9 재조정) 사용자 요청 — Stockfish 18(정식, 셋 중 가장 강력함)을 목록 맨 위로.
const ANALYSIS_ENGINE_IDS = ["full18", "lite", "full17"];
// (성능) SharedArrayBuffer 기반 멀티스레드 Stockfish는 교차 출처 격리(Cross-Origin-Opener/Embedder
// Policy)가 걸린 페이지에서만 쓸 수 있다 — vite.config.js(개발)·vercel.json(배포)에서 헤더를 설정해
// 뒀을 때만 true가 된다. 격리가 안 된 환경(구형 브라우저, 헤더 미지원 배포지 등)에서는 이 값이
// false라 아래 engineBootList가 조용히 기존 단일 스레드 빌드로만 폴백한다.
function crossOriginIsolatedOK() {
  return typeof SharedArrayBuffer !== "undefined" && typeof window !== "undefined" && window.crossOriginIsolated === true;
}
// (v0.2.4) 분석 엔진의 스레드 수를 2로 고정한다 — 기기 코어 수에 비례해 늘리지 않는다.
function mainEngineThreads() { return 2; }
// 부팅 시도 목록 — 격리가 가능하면 멀티스레드 빌드(같은 출처만)를 맨 앞에 두고, 그 뒤로 기존
// 단일 스레드 빌드(로컬 → CDN)를 그대로 이어 붙여, 멀티스레드 부팅이 실패해도 기존 폴백 경로가
// 그대로 살아있게 한다.
function engineBootList(profileId, threads) {
  const profile = ENGINE_PROFILES[profileId] || ENGINE_PROFILES[defaultEnginePref()];
  // (v0.2.0 버그 수정) Stockfish 17.1(최고 성능) 프로필은 신경망이 조각(-part-N.wasm)째로 수십MB에
  // 달해, 다 받아 이어 붙이고 컴파일하는 데 기존 4초 부팅 타임아웃보다 오래 걸릴 수 있다 — 이
  // 타임아웃이 먼저 끝나 워커를 강제 종료하면 파일을 받던 중이라 "연결 실패"로 이어졌다. 신경망이
  // 조각나 있는 프로필(profile.parts)만 훨씬 넉넉한 타임아웃을 준다(가벼운 기존 두 엔진은 그대로 4초).
  // (v0.5.1 버그 수정, 사용자 제보) "Stockfish 18을 고르면 항상 연결 실패로 멈춘다" — Stockfish
  // 18(정식)의 신경망은 조각을 다 합치면 약 108MB로, 같은 조각 방식을 쓰는 17.1(약 80MB)보다도 크고
  // 게다가 앱과 같은 출처가 아닌 외부 CDN(Vercel Blob)에서 받는다(위 ENGINE_PROFILES.full18 주석
  // 참고) — 그런데도 그 17.1과 똑같이 45초 타임아웃을 나눠 쓰고 있었다. 45초 안에 108MB를 받으려면
  // 최소 초당 2.4MB(≈19Mbps) 이상 꾸준히 나와야 하는데, 특히 첫 요청이라 캐시도 없는 외부 CDN
  // 왕복까지 겹치면 흔한 가정용/모바일 환경에서도 이 기준을 못 채우는 경우가 많다 — 17.1의 옛
  // 버그(README v0.2.0)와 정확히 같은 종류로, 다 받기도 전에 타임아웃이 먼저 끝나 워커를 강제
  // 종료해 "연결 실패"로 보였다. profile에 개별 부팅 타임아웃을 지정할 수 있게 하고(bootTimeoutMs
  // 필드, 없으면 기존처럼 parts 여부로 45초/4초 결정), full18만 90초로 넉넉히 늘렸다.
  const bootTimeoutMs = profile.bootTimeoutMs != null ? profile.bootTimeoutMs : (profile.parts ? 45000 : 4000);
  const list = profile.urls.map((url) => ({ url, threads: 1, bootTimeoutMs }));
  if (profile.mtUrl && crossOriginIsolatedOK()) list.unshift({ url: profile.mtUrl, threads, bootTimeoutMs });
  return list;
}
const ENGINE_PREF_KEY = "occ_engine_pref";
// (v0.2.4) 기기 종류와 무관하게 항상 Stockfish 18 Lite를 기본값으로 쓴다.
function defaultEnginePref() { return "lite"; }
function loadEnginePref() {
  try { const v = window.localStorage.getItem(ENGINE_PREF_KEY); if (v && ANALYSIS_ENGINE_IDS.includes(v)) return v; } catch { }
  return defaultEnginePref();
}
function saveEnginePref(v) { try { window.localStorage.setItem(ENGINE_PREF_KEY, v); } catch { } }
// Lichess Explorer가 로그인(OAuth 토큰)을 요구하므로, 토큰을 서버에만 보관하는
// /api/lichess 프록시(Vercel 서버리스 함수, api/lichess.js)를 거쳐 호출한다.

// (v0.0.5 성능) 알림·채팅·친구요청처럼 "다른 유저 행동으로 내 화면이 바뀌어야 하는" 데이터는 3~30초
// 폴링 대신 Postgres 변경을 실시간으로 밀어받는다. filter는 PostgREST 문법 그대로(예: "to_uid=eq.<uid>").
// 소켓이 끊긴 채 조용히 죽는 경우를 대비해 아주 느슨한 간격(fallbackMs)으로 안전망 재조회도 겸한다.
// (v0.1.1 버그 수정) 채널 이름을 table+filter로만 지었더니, 서로 다른 컴포넌트가 완전히 같은
// table+filter를 동시에 구독하는 경우(예: 헤더의 "안읽은 채팅" 배지와, 채팅창을 열었을 때 그
// 안에서 또 구독하는 ChatPanel — 둘 다 "chat_messages, to_uid=eq.<나>"를 구독) 정확히 같은
// Realtime 채널 토픽을 같은 소켓에 두 번 join하게 됐다. 서버가 기존 join을 강제로 끊어내고
// 클라이언트는 그걸 다시 재연결하려 시도하는 과정이 계속 반복되며(서로가 서로를 계속 밀어냄) 짧은
// 간격으로 무한히 재연결·재구독이 일어나 CPU를 계속 잡아먹었다 — 이게 "채팅 버튼을 누르면
// 사이트가 먹통이 된다"는 신고의 원인이었다. 훅이 마운트될 때마다 항상 다른 채널 이름을 쓰도록
// 인스턴스별 고유 id를 더해, 같은 table+filter를 여러 컴포넌트가 동시에 구독해도 서로 다른
// 채널(같은 postgres_changes 필터를 각자 독립적으로 받는)로 취급되게 한다.
let rtChanSeq = 0;
function useRealtimeTable(table, filter, onEvent, enabled, fallbackMs) {
  const cbRef = useRef(onEvent);
  cbRef.current = onEvent;
  const chanIdRef = useRef(null);
  if (chanIdRef.current == null) chanIdRef.current = ++rtChanSeq;
  useEffect(() => {
    if (!enabled || !sbClient || !filter) return;
    const channel = sbClient
      .channel("rt:" + table + ":" + filter + ":" + chanIdRef.current)
      .on("postgres_changes", { event: "*", schema: "public", table, filter }, (payload) => cbRef.current && cbRef.current(payload))
      .subscribe();
    const id = fallbackMs ? setInterval(() => cbRef.current && cbRef.current(null), fallbackMs) : null;
    return () => { sbClient.removeChannel(channel); if (id) clearInterval(id); };
  }, [table, filter, enabled, fallbackMs]);
}

