  const promise = (prof && prof.parts)
    ? bootWorkersStaggered(urls, size, HEAVY_ENGINE_BOOT_BATCH)
    : Promise.all(Array.from({ length: size }, () => bootAnalysisWorker(urls))).then((ws) => ws.filter(Boolean));
