    const path = [...sans, san];
    let out = chesscom.games.filter((g) => g.moves.length >= path.length && path.every((s, i) => g.moves[i] === s));
    if (myTimeFilter !== "all") out = out.filter((g) => g.timeClass === myTimeFilter);
