    if (!el || !ids.length) return;
    const frontier = ids.find((id) => { const st = lessonNodeState(mainQuest, id); return st === "available" || st === "progress"; }) || layout.roots[0] || ids[0];
    if (!frontier || !layout.pos[frontier]) return;
