  // 마저 나간다), "button"이면 헤더의 닫기 버튼을 눌러 들어온 요청(확인 후 closePlay()를 그대로 부른다).
  const pendingPlayExitRef = useRef(null);
  const [playExitConfirmOpen, setPlayExitConfirmOpen] = useState(false);
